"use client";

import { useDictionary } from "@/hooks/useDictionary";
import SozlukEkrani from "@/components/SozlukEkrani";

export default function HomePage() {
  const dictionary = useDictionary();

  // Hook'tan gelen isimleri SozlukEkrani prop'larına eşliyoruz:
  const words = (dictionary as Record<string, any>).sozlukSonuclari || (dictionary as Record<string, any>).filteredWords || [];
  const totalCount = dictionary.wordsCount || 0;

  return (
    <SozlukEkrani
      words={words}
      loading={dictionary.loading}
      totalCount={totalCount}
    />
  );
}