"use client";

import React, { memo } from "react";
import Image from "next/image";
import type { ExtendedDictionaryItem } from "@/types/dictionary";

export interface KelimeKartiProps {
  item: ExtendedDictionaryItem;
  theme?: "default" | "kirmizi" | "sari" | "featured";
  size?: "compact" | "medium" | "large";
  fontSize?: number;
  showBranding?: boolean;
  onSelect?: (item: ExtendedDictionaryItem) => void;
}

export const KelimeKarti = memo(function KelimeKarti({
  item,
  theme = "kirmizi",
  size = "medium",
  fontSize,
  showBranding = true,
  onSelect,
}: KelimeKartiProps) {
  // cva kütüphanesi yerine saf Tailwind stil eşleştirmesi
  const themeClasses: Record<string, string> = {
    default:
      "bg-white dark:bg-gray-800 border-slate-200 dark:border-gray-700 text-slate-800 dark:text-gray-100",
    kirmizi:
      "bg-white dark:bg-gray-800 border-l-4 border-l-[#FF4030] border-slate-200 dark:border-gray-700 text-gray-800 dark:text-gray-100",
    sari:
      "bg-white dark:bg-gray-800 border-l-4 border-l-[#FFC604] border-slate-200 dark:border-gray-700 text-gray-800 dark:text-gray-100",
    featured:
      "bg-slate-900 text-white border-slate-800 shadow-lg dark:bg-slate-950",
  };

  const sizeClasses: Record<string, string> = {
    compact: "p-3 text-sm gap-1.5",
    medium: "p-5 text-base gap-2",
    large: "p-6 text-lg gap-3",
  };

  const kelimeMetni = String(item?.kelime ?? item?.word ?? "");
  const tanimMetni = String(item?.tanim ?? item?.meaning ?? item?.full_definition_in_html ?? "");
  const sozlukAdi = String(item?.sozlukAdi ?? item?.dictionaryName ?? "Sözlük");

  if (!tanimMetni) return null;

  return (
    <article
      role="button"
      tabIndex={0}
      onClick={() => onSelect?.(item)}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onSelect?.(item);
        }
      }}
      className={`relative flex flex-col rounded-xl border transition-all duration-200 ease-in-out cursor-pointer group shadow-sm hover:shadow-md select-none ${
        themeClasses[theme] || themeClasses.kirmizi
      } ${sizeClasses[size] || sizeClasses.medium}`}
    >
      <header className="flex justify-between items-center border-b border-slate-100 dark:border-gray-700/60 pb-2">
        <h3
          className="font-bold tracking-tight text-blue-600 dark:text-blue-400 group-hover:text-blue-700 transition-colors"
          style={fontSize ? { fontSize: `${fontSize}px` } : undefined}
        >
          {kelimeMetni}
        </h3>

        <div className="flex items-center gap-2">
          <span className="text-xs px-2.5 py-0.5 rounded-full bg-slate-100 dark:bg-gray-700 text-slate-600 dark:text-gray-300 font-medium">
            {sozlukAdi}
          </span>
          {showBranding && (
            <Image
              src="/logo/logo.png"
              alt="Açık Mektep Logosu"
              width={24}
              height={24}
              className="object-contain"
            />
          )}
        </div>
      </header>

      <div
        className="text-slate-700 dark:text-gray-300 leading-relaxed line-clamp-3 my-2"
        style={fontSize ? { fontSize: `${Math.max(fontSize - 2, 12)}px` } : undefined}
        dangerouslySetInnerHTML={{ __html: tanimMetni }}
      />

      {showBranding && (
        <footer className="mt-auto pt-3 border-t border-slate-100 dark:border-gray-700/50 flex justify-end">
          <Image
            src="/logo/logo.png"
            alt="Kurumsal İmza"
            width={100}
            height={32}
            className="opacity-75 dark:opacity-60 object-contain"
          />
        </footer>
      )}
    </article>
  );
});