"use client";

import { memo } from "react";

// src/components/SearchBox.tsx
export interface SearchBoxProps {
  searchTerm: string;
  setSearchTerm: (value: string) => void;
  onLetterClick: (letter: string) => void;
  isKlavyeOpen: boolean;
  setIsKlavyeOpen: React.Dispatch<React.SetStateAction<boolean>>;
}

const CERKESCE_HARFLER = [
  "Ӏ", "I", "ӏ", "А", "Б", "В", "Г", "Гу", "Гъ", "Гъу", "Д"
] as const;

export const SearchBox = memo(function SearchBox({
  searchTerm,
  setSearchTerm,
  onLetterClick,
  isKlavyeOpen,
  setIsKlavyeOpen,
}: SearchBoxProps) {
  return (
    <div className="w-full space-y-3">
      {/* Arama Input Alanı */}
      <div className="relative flex items-center">
        <input
          type="text"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          placeholder="Kelime veya anlam ara..."
          aria-label="Kelime veya anlam arama girdisi"
          className="w-full rounded-xl border border-gray-300 bg-white py-3 pl-10 pr-28 text-gray-900 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 dark:border-gray-700 dark:bg-gray-800 dark:text-gray-100"
        />
        <span 
          className="absolute left-3 text-gray-400 select-none" 
          aria-hidden="true"
        >
          🔍
        </span>

        {/* Temizle & Klavye Butonları */}
        <div className="absolute right-3 flex items-center gap-2">
          {searchTerm && (
            <button
              type="button"
              onClick={() => setSearchTerm("")}
              aria-label="Arama metnini temizle"
              className="px-1 text-sm font-bold text-gray-400 transition-colors hover:text-gray-600 dark:hover:text-gray-200"
            >
              ✕
            </button>
          )}

          <button
            type="button"
            onClick={() => setIsKlavyeOpen(!isKlavyeOpen)}
            aria-label="Sanal klavyeyi aç veya kapat"
            className={`rounded border px-2 py-1 text-xs transition-colors ${
              isKlavyeOpen
                ? "border-blue-600 bg-blue-600 text-white"
                : "border-gray-300 bg-gray-100 text-gray-700 dark:border-gray-600 dark:bg-gray-700 dark:text-gray-300"
            }`}
          >
            ⌨️ Klavye
          </button>
        </div>
      </div>

      {/* Hızlı Çerkesçe Harf Butonları */}
      <div className="flex flex-wrap gap-1.5 pt-1">
        {CERKESCE_HARFLER.map((harf) => (
          <button
            key={harf}
            type="button"
            onClick={() => onLetterClick(harf)}
            aria-label={`${harf} harfini aramaya ekle`}
            className="rounded border border-gray-200 bg-gray-100 px-2.5 py-1 text-xs font-semibold text-gray-800 transition-colors hover:bg-blue-50 dark:border-gray-700 dark:bg-gray-800 dark:text-gray-200 dark:hover:bg-blue-900/40"
          >
            {harf}
          </button>
        ))}
      </div>
    </div>
  );
});

export default SearchBox;