'use client';

import React, { memo } from "react";
import type { RefObject, Dispatch, SetStateAction } from "react";

export interface AkilliKlavyeProps {
  inputRef: RefObject<HTMLInputElement | null>;
  sorgu: string;
  setSorgu: Dispatch<SetStateAction<string>>;
  metinBoyutu?: number;
  karanlikMod?: boolean;
  onTuşBas?: (karakter: string) => void;
  onKeyClick?: (key: string) => void;
  onDelete?: () => void;
}

const CERKESCE_KARAKTERLER = [
  "I", "ӏ", "Гъ", "Дж", "Дз", "Къ", "КӀ", "ПӀ", "ТӀ", "Хь", "Хъ", "ЦӀ", "ШӀ", "ЩӀ"
];

export const AkilliKlavye = memo(function AkilliKlavye({
  inputRef,
  sorgu,
  setSorgu,
  metinBoyutu = 16,
  karanlikMod = false,
  onTuşBas,
  onKeyClick,
  onDelete,
}: AkilliKlavyeProps) {
  const handleKarakterEkle = (karakter: string) => {
    setSorgu((prev: string) => prev + karakter);
    onTuşBas?.(karakter);
    onKeyClick?.(karakter);
    inputRef.current?.focus();
  };

  const handleSil = () => {
    setSorgu((prev: string) => prev.slice(0, -1));
    onDelete?.();
    inputRef.current?.focus();
  };

  return (
    <div
      role="region"
      aria-label="Çerkesçe Akıllı Klavye ve Arama Alanı"
      className={`flex flex-col gap-3 p-4 rounded-xl border transition-colors shadow-sm ${
        karanlikMod
          ? "bg-slate-900 border-slate-800 text-slate-100"
          : "bg-slate-50 border-slate-200 text-slate-800"
      }`}
    >
      <div className="relative w-full">
        <input
          ref={inputRef}
          type="text"
          value={sorgu}
          onChange={(e) => setSorgu(e.target.value)}
          placeholder="Aramak istediğiniz kelimeyi yazın..."
          className={`w-full px-4 py-2.5 rounded-lg border outline-none transition-all focus:ring-2 focus:ring-amber-500 ${
            karanlikMod
              ? "bg-slate-800 border-slate-700 text-white placeholder-slate-400"
              : "bg-white border-slate-300 text-slate-900 placeholder-slate-500"
          }`}
          style={{ fontSize: `${metinBoyutu}px` }}
        />
      </div>

      <div className="flex flex-wrap items-center gap-1.5">
        {CERKESCE_KARAKTERLER.map((char) => (
          <button
            key={char}
            type="button"
            onClick={() => handleKarakterEkle(char)}
            style={{ fontSize: `${metinBoyutu}px` }}
            className="px-3 py-1.5 rounded-md bg-amber-600 hover:bg-amber-700 active:scale-95 text-white font-medium transition-all focus:outline-none focus:ring-2 focus:ring-amber-400 select-none"
          >
            {char}
          </button>
        ))}

        <button
          type="button"
          onClick={handleSil}
          aria-label="Son karakteri sil"
          style={{ fontSize: `${metinBoyutu}px` }}
          className="ml-auto px-3 py-1.5 rounded-md bg-slate-700 hover:bg-slate-800 active:scale-95 text-white font-medium transition-all focus:outline-none focus:ring-2 focus:ring-slate-400 select-none"
        >
          Sil ⌫
        </button>
      </div>
    </div>
  );
});

export default AkilliKlavye;